objects.push({type:'point',x:0,z:-17,name:'CROSSROADS'});objects.push({type:'base',x:0,z:-77,name:'COMMAND POST'});
const ally=faction;for(let i=0;i<50;i++){let a=rand(0,Math.PI*2),r=rand(4,32),z=rand(-31,32);soldiers.push({x:Math.cos(a)*r,z,team:'ally',hp:100,aim:rand(0,2),state:'advance',uniform:ally})}for(let i=0;i<50;i++){soldiers.push({x:rand(-17,17),z:rand(-61,-26),team:'enemy',hp:100,aim:rand(0,2),state:'defend',uniform:ally==='USSR'?'GERMANY':'USSR'})}}
let keys={},pointerLocked=false;addEventListener('keydown',e=>{keys[e.code]=true;if(scene==='game'&&!paused){if(e.code==='KeyR')reload();if(e.code==='KeyG')dig();if(e.code==='KeyE')interact();if(e.code==='Escape'){paused=true;openSub('pause')}}});addEventListener('keyup',e=>keys[e.code]=false);canvas.addEventListener('click',()=>{if(scene==='game'&&!paused){canvas.requestPointerLock?.();fire()}});document.addEventListener('pointerlockchange',()=>pointerLocked=document.pointerLockElement===canvas);document.addEventListener('mousemove',e=>{if(scene==='game'&&!paused&&pointerLocked){player.yaw+=e.movementX*.0022;player.pitch=clamp(player.pitch-e.movementY*.0017,-.45,.45)}});canvas.addEventListener('contextmenu',e=>e.preventDefault());
function reload(){if(player.ammo<35&&player.reload<=0){player.reload=1.05;notify(lang==='en'?'RELOADING…':'ПЕРЕЗАРЯДКА…')}}function dig(){if(Math.hypot(player.x,player.z+17)<26){trench.push({x:player.x,z:player.z});objects.push({type:'trench',x:player.x,z:player.z,w:1.8,d:2.5});notify(lang==='en'?'SHALLOW TRENCH DUG':'ОКОП ВЫРЫТ')}else notify(lang==='en'?'TOO EXPOSED TO DIG HERE':'ЗДЕСЬ НЕЛЬЗЯ КОПАТЬ')}
function interact(){notify(lang==='en'?'NO VEHICLE IN REACH · SQUAD HOLDING THE LINE':'МАШИНЫ РЯДОМ НЕТ · ОТРЯД ДЕРЖИТ РУБЕЖ')}
function notify(s){const n=$('#toast');n.textContent=s;n.classList.add('on');toastTimer=1.8}
function fire(){if(player.reload>0)return;if(player.ammo<=0){reload();return}player.ammo--;let best=null,bd=999;for(const s of soldiers){if(s.team!=='enemy'||s.hp<=0)continue;let dx=s.x-player.x,dz=s.z-player.z,dist=Math.hypot(dx,dz),a=Math.atan2(dx,-dz)-player.yaw;a=Math.atan2(Math.sin(a),Math.cos(a));if(dist<54&&Math.abs(a)<.09+1.6/dist&&dist<bd){bd=dist;best=s}}if(best){best.hp-=rand(45,90);shots.push({x:best.x,z:best.z,time:.15});if(best.hp<=0){player.kills++;if(Math.random()<.14)notify(lang==='en'?'HOSTILE DOWN':'ПРОТИВНИК УСТРАНЁН')}}else shots.push({x:player.x+Math.sin(player.yaw)*24,z:player.z-Math.cos(player.yaw)*24,time:.11});updateHud()}
let touchMove={x:0,y:0};const stick=$('#stick');if(stick){let drag=false;stick.addEventListener('pointerdown',e=>{drag=true;stick.setPointerCapture(e.pointerId);moveStick(e)});stick.addEventListener('pointermove',e=>{if(drag)moveStick(e)});stick.addEventListener('pointerup',()=>{drag=false;touchMove={x:0,y:0}});function moveStick(e){let r=stick.getBoundingClientRect();touchMove.x=clamp((e.clientX-r.left-r.width/2)/42,-1,1);touchMove.y=clamp((e.clientY-r.top-r.height/2)/42,-1,1)}}$('#fireTouch').onpointerdown=e=>{e.preventDefault();fire()};$('#jumpTouch').onclick=()=>interact();
