function updateHud(){const pct=Math.floor(control);$('#controlPct').textContent=pct+'%';$('#controlBar').style.width=pct+'%';$('#allyCount').textContent=(faction==='USSR'?'USSR':'GER')+' '+Math.max(0,50-Math.floor(player.kills*.17));$('#enemyCount').textContent=(faction==='USSR'?'GER':'USSR')+' '+Math.max(0,50-player.kills);$('#ammo').innerHTML=player.ammo+' <small>MAG 01 &nbsp; · &nbsp; ∞ RESERVE</small>';$('#weaponName').textContent=faction==='USSR'?'PPSh-41':'MP 40'}
function update(dt){if(scene!=='game'||paused)return;clock+=dt;player.reload=Math.max(0,player.reload-dt);if(player.reload===0&&$('#toast').textContent.includes('RELOAD'))player.ammo=35;let f=(keys.KeyW?1:0)-(keys.KeyS?1:0)-touchMove.y,side=(keys.KeyD?1:0)-(keys.KeyA?1:0)+touchMove.x;let len=Math.hypot(f,side);if(len){f/=len;side/=len;let sp=keys.ShiftLeft?8:5.2;player.x+= (Math.cos(player.yaw)*side+Math.sin(player.yaw)*f)*sp*dt;player.z+= (Math.sin(player.yaw)*side-Math.cos(player.yaw)*f)*sp*dt;player.x=clamp(player.x,-23,23);player.z=clamp(player.z,-91,37);player.walk+=dt*sp}
