if(Math.hypot(player.x,player.z+17)<8){let enemies=soldiers.filter(s=>s.team==='enemy'&&s.hp>0&&Math.hypot(s.x,s.z+17)<10).length;let rate=enemies?-.7:.19;control=clamp(control+rate*dt,0,100);if(control>=100){$('#objTitle').textContent=t('victory');$('#objSub').textContent='COMMAND POST · SECURED';}else{$('#objTitle').textContent=t('capture');$('#objSub').textContent=enemies?(lang==='en'?'SECTOR B · CONTESTED':'СЕКТОР Б · БОЙ'):t('sector')}updateHud()}else{$('#objTitle').textContent=t('capture');$('#objSub').textContent='SECTOR B · '+Math.round(Math.hypot(player.x,player.z+17))+' m'}for(const p of shots)p.time-=dt;shots=shots.filter(p=>p.time>0);if(toastTimer>0){toastTimer-=dt;if(toastTimer<=0)$('#toast').classList.remove('on')}}
// Projection and painter's-order rendering for a stylized, walkable first-person 3D battlefield.
function project(x,y,z){let dx=x-player.x,dz=z-player.z,cs=Math.cos(player.yaw),sn=Math.sin(player.yaw),cx=dx*cs-dz*sn,cz=dx*sn+dz*cs;if(cz<.35)return null;let focal=H*.84,scale=focal/cz;return {x:W/2+cx*scale,y:H*.53+(1.58-y)*scale+player.pitch*H*.55,scale,z:cz}}
function poly(points,color,stroke){ctx.fillStyle=color;ctx.beginPath();points.forEach((p,i)=>{if(!p)return;if(i===0)ctx.moveTo(p.x,p.y);else ctx.lineTo(p.x,p.y)});ctx.closePath();ctx.fill();if(stroke){ctx.strokeStyle=stroke;ctx.lineWidth=1;ctx.stroke()}}
