function drawSky(){let g=ctx.createLinearGradient(0,0,0,H*.62);g.addColorStop(0,'#78837d');g.addColorStop(.52,'#b3b09a');g.addColorStop(1,'#858676');ctx.fillStyle=g;ctx.fillRect(0,0,W,H*.63);let ground=ctx.createLinearGradient(0,H*.48,0,H);ground.addColorStop(0,'#61664f');ground.addColorStop(.35,'#454a38');ground.addColorStop(1,'#282d23');ctx.fillStyle=ground;ctx.fillRect(0,H*.48,W,H*.52);ctx.fillStyle='#cec3a1';ctx.globalAlpha=.12;ctx.fillRect(0,H*.45,W,H*.025);ctx.globalAlpha=1}
